//Inspired by https://www.shadertoy.com/view/MddGWN 
float hash(float n) {
    n = fract(n * 1.123);
    n *= n + 22.22;
    n *= n;
    return fract(n);
}

vec2 pAt(float t, float pID, int total) {
    float angle = fract(mod(pID/float(total), 0.25));
    return hash(t + pID) * posAt(angle, (int(pID) % 2 != 0) ? 1.0 : 4.0);
}

// Toggle w/ texture by commenting below
#define BG

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    // [Setup]
    vec2 uv = (2.0*fragCoord - iResolution.xy) / min(iResolution.x, iResolution.y);
    // Move to the bottom
    uv.y += 1.0;

    // [Parameters (for particles)]
    int p_count;
    p_count = 10;
#ifndef BG
    // only for a flamethrow effect
    p_count = int(mix(float(p_count), float(p_count)*3.0, iMouse.w>0.0));
#endif

    // Flame
    float size     = mix(0.6, float(p_count)*iMouse.y*0.0005, iMouse.w<0.0);
    p_count        = int(mix(float(p_count), float(p_count)*iMouse.x*0.005, iMouse.w<0.0));
    vec4  color    = vec4(0.55, 0.4, 0.2, 1.0);
    float speed    = 1.0;
    float radiance = 0.5;

    // [Accumulate]
    float time = fract(iTime * speed*0.001);
#ifdef BG 
    vec4 out_v = vec4(vec3(radiance), 1.0);
    float factor = 0.5;
#else
    vec4 out_v = vec4(vec3(radiance-1.0), 1.0);
    float factor = 0.05;
#endif

    for(int i = 1; i < p_count; i++) {
        vec2 pos = pAt(time, float(i), p_count);
        float dist = length(uv * (1.0 / size) - pos);
        float brightness = factor / (dist * dist);
        out_v += color * brightness;
    }

    // [Output/Layer]
#ifdef BG
    vec4 blendeduv = color*(texture(iChannel0,uv)*0.8 +
                        texture(iChannel1,uv)*0.2 +
                        texture(iChannel2,uv)*0.3);
    fragColor = vec4(out_v * blendeduv);
#else
    fragColor = vec4(out_v);
#endif
}

#define HALFPI 1.57079632679489661923
#define TAU (HALFPI*4.0)

// Radical sine approximation (optimized)
float rsin(float x) {
    float a = 1.0 - 2.0 * x + 2.0 * x * x;
    float invSqrtA = inversesqrt(a);
    return x * invSqrtA;
}

// Radical cosine approximation (optimized)
float rcos(float x) {
    float a = 1.0 - 2.0 * x + 2.0 * x * x;
    float invSqrtA = inversesqrt(a);
    return (1.0 - x) * invSqrtA;
}

// Quadrant logic (branchless)
vec2 getQuadrant(int quadrant, float c, float s) {
    /*   -x,+y  |  +x,+y
        ___q2___|___q3____
         -x,-y  |  +x,-y
           q1   |    q0    */

    // 1 if even, 0 if odd
    float qEven = 1.0 - float(quadrant / 2 == 0);
    // 1 if first two quadrants, 0 otherwise
    float qFirstHalf = 1.0 - float(quadrant >= 2);

    // Swap c and s based on quadrant parity
    float x = mix(s, c, qEven);
    float y = mix(c, s, qEven);

    // Flip y for upper/lower halves
    y *= mix(-1.0, 1.0, qFirstHalf);
    // Flip x for left/right halves
    x *= mix(-1.0, 1.0, float(quadrant == 0 || quadrant == 3));

    return vec2(x, y);
}

vec2 posAt(float param, float quadrantCount) {
    int quadrant = int(mod(quadrantCount, 4.0));
    return getQuadrant(quadrant, rcos(param), rsin(param));
}
